using System;using System.IO;using System.Windows.Forms;
namespace ScoreModern {
 public static class NativeDiskDialogChoice {
  static bool files=NativeSettings.Read("disk-file-dialogs")=="windows",folders=NativeSettings.Read("disk-folder-dialogs")=="windows";
  public static bool Files{get{return !NativeScoreBehaviour.Enabled&&files;}}
  public static bool Folders{get{return !NativeScoreBehaviour.Enabled&&folders;}}
  internal static void Set(bool useFiles,bool useFolders,bool save){files=useFiles;folders=useFolders;if(save){NativeSettings.WriteAllText("disk-file-dialogs",files?"windows":"score");NativeSettings.WriteAllText("disk-folder-dialogs",folders?"windows":"score");}}
  internal static void AddMenu(ContextMenuStrip menu){var f=new ToolStripMenuItem("Use Windows file dialogs for load and save prompts");var d=new ToolStripMenuItem("F7 folders: use Windows folder dialogs");f.Click+=(s,e)=>Set(!files,folders,true);d.Click+=(s,e)=>Set(files,!folders,true);menu.Items.Add(f);menu.Items.Add(d);menu.Opening+=(s,e)=>{f.Checked=Files;d.Checked=Folders;f.Enabled=d.Enabled=!NativeScoreBehaviour.Enabled;};}
 }
 public sealed partial class Editor {
  Func<string,string> diskFileDialogSelection;
  Func<int,string> diskFolderDialogSelection;
  string ChooseWindowsDiskFile(string verb){if(diskFileDialogSelection!=null)return diskFileDialogSelection(verb);string initial=NativeOpenFolder.InitialDirectory(source);if(verb=="SA"){using(var dialog=new SaveFileDialog{Title="Save SCORE file",Filter="SCORE documents (*.mus;*.pag)|*.mus;*.pag|All files (*.*)|*.*",FileName=String.IsNullOrEmpty(current)?"SCORE.MUS":Path.GetFileName(current),InitialDirectory=NativeOutputLocation.EnsureFolder(source),DefaultExt=String.IsNullOrEmpty(current)?"mus":Path.GetExtension(current).TrimStart('.'),RestoreDirectory=true,OverwritePrompt=false})return dialog.ShowDialog(this)==DialogResult.OK?dialog.FileName:null;}using(var dialog=new OpenFileDialog{Title=verb=="G"?"Load SCORE file":verb=="GM"?"Append SCORE file":verb=="RE"?"Read SCORE command file":"Choose file to delete",Filter=verb=="RE"?"SCORE command/text files|*.COM;*.TXT|All files (*.*)|*.*":"SCORE documents (*.mus;*.pag)|*.mus;*.pag|All files (*.*)|*.*",InitialDirectory=initial,RestoreDirectory=true})return dialog.ShowDialog(this)==DialogResult.OK?dialog.FileName:null;}
  string ChooseWindowsDiskFolder(int key){if(diskFolderDialogSelection!=null)return diskFolderDialogSelection(key);using(var dialog=new FolderBrowserDialog{Description=key==5?"Choose a folder to list":key==6?"Choose a folder on the drive to use":"Choose the current working folder",SelectedPath=Directory.GetCurrentDirectory()})return dialog.ShowDialog(this)==DialogResult.OK?dialog.SelectedPath:null;}
  bool WindowsDiskFunction(int key){return mode==ScreenMode.Disk&&TryWindowsDiskSelection(key);}
  bool TryWindowsDiskSelection(int key){if(NativeDiskDialogChoice.Files&&(key>=1&&key<=4||key==8)){string verb=key==1?"G":key==2?"SA":key==3?"GM":key==4?"RE":"DEL";string path=ChooseWindowsDiskFile(verb);if(path!=null){StartDiskFilename(verb);SubmitDiskFilename(path);}else{Message("");UpdateClassic();command.Focus();}return true;}if(NativeDiskDialogChoice.Folders&&key>=5&&key<=7){string path=ChooseWindowsDiskFolder(key);if(path!=null){path=Path.GetFullPath(path);if(key==5)ShowScoreDirectory(Path.Combine(path,"*.*"));else if(key==7){Directory.SetCurrentDirectory(path);Message("");UpdateClassic();}else{string root=Path.GetPathRoot(path);if(root.Length<2||root[1]!=':')throw new NotSupportedException("DRV requires a local drive; use SET PATH for a network folder.");StartDriveChange();SubmitDriveChange(root.Substring(0,1));}}command.Focus();return true;}return false;}
  internal void CheckWindowsDiskChoices(){bool oldFiles=NativeDiskDialogChoice.Files,oldFolders=NativeDiskDialogChoice.Folders,oldStrict=NativeScoreBehaviour.Enabled;string directory=Directory.GetCurrentDirectory();var original=score.Encode();try{NativeScoreBehaviour.Set(false,false);NativeDiskDialogChoice.Set(true,true,false);diskFileDialogSelection=verb=>null;diskFolderDialogSelection=key=>null;mode=ScreenMode.Disk;foreach(int key in new[]{1,2,3,4,5,6,7,8}){if(!DiskFileFunction(key)||mode!=ScreenMode.Disk||pendingDiskFilename!=null||pendingDriveChange||pendingDiskDelete!=null)throw new Exception("Native disk cancellation altered state.");}if(!System.Linq.Enumerable.SequenceEqual(original,score.Encode())||Directory.GetCurrentDirectory()!=directory)throw new Exception("Native disk cancellation mutated document/path.");diskFolderDialogSelection=key=>Path.GetTempPath();DiskFileFunction(7);if(Path.GetFullPath(Directory.GetCurrentDirectory()).TrimEnd('\\')!=Path.GetFullPath(Path.GetTempPath()).TrimEnd('\\'))throw new Exception("Native folder choice did not set working directory.");Directory.SetCurrentDirectory(directory);NativeScoreBehaviour.Set(true,false);if(NativeDiskDialogChoice.Files||NativeDiskDialogChoice.Folders)throw new Exception("Strict preset allowed Windows disk dialogs.");mode=ScreenMode.Disk;DiskFileFunction(1);if(pendingDiskFilename!="G")throw new Exception("Strict F7 lost original filename prompt.");DiskFilenameKey(new KeyEventArgs(Keys.Escape));Console.WriteLine("PASS eight Windows disk cancellations, unchanged score/path, folder selection and strict SCORE prompt.");}finally{diskFileDialogSelection=null;diskFolderDialogSelection=null;Directory.SetCurrentDirectory(directory);NativeScoreBehaviour.Set(oldStrict,false);NativeDiskDialogChoice.Set(oldFiles,oldFolders,false);}}
 }
 public static class NativeDiskDialogChoiceChecks {public static int Run(string root){try{using(var editor=new Editor(root,Path.Combine(root,"MUSDAT","PRACTICE.MUS"))){editor.Show();Application.DoEvents();editor.CheckWindowsDiskChoices();editor.Close();}return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}
}
